import React, { useState, useEffect } from 'react';
import AdvancedRegistration from './AdvancedRegistration';
import TelegramVerification from './TelegramVerification';
import { FiMail, FiLock, FiEye, FiEyeOff } from 'react-icons/fi';
import { FcGoogle } from 'react-icons/fc';
import '../styles/AdvancedAuth.css';
import { PasswordSecurityBadge } from './SecurityIndicator';

const AdvancedAuth = ({ onLogin, onRegister, onGoogleLogin, onClose }) => {
  const [mode, setMode] = useState('login'); // 'login', 'register', 'telegram-verify'
  const [loginData, setLoginData] = useState({ email: '', password: '' });
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [registrationResult, setRegistrationResult] = useState(null);

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      await onLogin(loginData.email, loginData.password);
    } catch (error) {
      console.error('Ошибка входа:', error);
      const errorMessage = error.response?.data?.detail || 
                          error.response?.data?.message || 
                          'Неверный email или пароль';
      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleRegistrationSuccess = async (registrationData) => {
    try {
      console.log('Вызов реальной функции регистрации с данными:', registrationData);
      const result = await onRegister(registrationData);
      console.log('Регистрация успешна:', result);
      
      // Проверяем, что результат содержит verification_id
      if (result && result.verification_id) {
        // Сохраняем результат регистрации и переходим к Telegram-верификации
        setRegistrationResult(result);
        setMode('telegram-verify');
      } else {
        console.error('Не получен verification_id от сервера');
        // Можно показать ошибку пользователю
      }
      
      return result;
    } catch (error) {
      console.error('Ошибка при регистрации в AdvancedAuth:', error);
      throw error; // Пробрасываем ошибку в AdvancedRegistration для обработки
    }
  };

  const handleTelegramVerificationComplete = (user) => {
    console.log('Telegram-верификация завершена:', user);
    // Закрываем модальное окно после успешной верификации
    onClose();
  };

  const handleBackToRegistration = () => {
    setMode('register');
    setRegistrationResult(null);
  };

  const handleInputChange = (field, value) => {
    setLoginData(prev => ({ ...prev, [field]: value }));
    if (error) setError(''); // Очищаем ошибку при изменении полей
  };

  if (mode === 'telegram-verify' && registrationResult) {
    return (
      <TelegramVerification
        verificationId={registrationResult.verification_id}
        onVerificationComplete={handleTelegramVerificationComplete}
        onBack={handleBackToRegistration}
      />
    );
  }

  if (mode === 'register') {
    return (
      <AdvancedRegistration
        onRegister={handleRegistrationSuccess}
        onSwitchToLogin={() => setMode('login')}
      />
    );
  }

  return (
    <div className="advanced-auth">
      <div className="auth-container">
        <div className="auth-header">
          <h1>Вход в аккаунт</h1>
          <p>Введите ваши данные для входа</p>
        </div>

        <form className="auth-form" onSubmit={handleLoginSubmit}>
          {error && (
            <div className="error-banner">
              <span>{error}</span>
            </div>
          )}

          <div className="form-group">
            <div className="input-with-icon">
              <FiMail className="input-icon" />
              <input
                type="email"
                className="form-input"
                value={loginData.email}
                onChange={(e) => handleInputChange('email', e.target.value)}
                placeholder="Email"
                disabled={isLoading}
                autoComplete="email"
                required
              />
            </div>
          </div>

          <div className="form-group">
            <div className="input-with-icon">
              <FiLock className="input-icon" />
              <input
                type={showPassword ? 'text' : 'password'}
                className="form-input"
                value={loginData.password}
                onChange={(e) => handleInputChange('password', e.target.value)}
                placeholder="Пароль"
                disabled={isLoading}
                autoComplete="current-password"
                required
              />
              <button
                type="button"
                className="password-toggle"
                onClick={() => setShowPassword(!showPassword)}
                disabled={isLoading}
                aria-label={showPassword ? 'Скрыть пароль' : 'Показать пароль'}
              >
                {showPassword ? <FiEyeOff /> : <FiEye />}
              </button>
            </div>
          </div>

          <button
            type="submit"
            className="auth-btn primary"
            disabled={isLoading || !loginData.email || !loginData.password}
          >
            {isLoading ? (
              <>
                <div className="btn-spinner" />
                Вход...
              </>
            ) : (
              'Войти'
            )}
          </button>
        </form>

        <div className="divider">
          <span>или</span>
        </div>

        <button
          className="auth-btn google"
          onClick={onGoogleLogin}
          disabled={isLoading}
        >
          <FcGoogle size={20} />
          Войти через Google
        </button>

        <div className="auth-footer">
          <p>
            Нет аккаунта?{' '}
            <button
              type="button"
              className="link-btn"
              onClick={() => setMode('register')}
              disabled={isLoading}
            >
              Зарегистрироваться
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

export default AdvancedAuth;